import { EvalResult } from '../schema';
import { latestPerConfig } from './report';

// docs/images/eval-connections.svg: for each model, connections found against connections
// invented, from the latest result of each config. Regenerated by `pnpm eval chart`.

type LabelSide = 'left' | 'right' | 'above' | 'below';
export interface ChartPoint { config: string; label: string; found: number; invented: number; total: number; highlight: boolean; side: LabelSide }

// With four points, each label's side is chosen by hand so nothing overlaps
export const CHART_CONFIGS: { config: string; label: string; highlight?: boolean; side: LabelSide }[] = [
  { config: 'deepseek-flash-top3', label: 'DeepSeek Flash, thinking off (default)', highlight: true, side: 'left' },
  { config: 'deepseek-flash-top3-thinking', label: 'DeepSeek Flash, thinking on', side: 'above' },
  { config: 'baseline-gemini-top3', label: 'Gemini 3.1 Flash Lite', side: 'below' },
  { config: 'qwen-local-top3', label: 'Qwen 2.5 7B (local)', side: 'right' },
];

/** Connections = pairs labeled actionable or tentative; invented = labeled irrelevant, called either. */
export function chartPoints(results: EvalResult[], dataset: string): ChartPoint[] {
  const latest = latestPerConfig(results).filter(r => r.meta.dataset === dataset);
  return CHART_CONFIGS.flatMap(({ config, label, highlight, side }) => {
    const r = latest.find(x => x.meta.config === config);
    const c = r?.triage.connection;
    if (!r || !c || c.recall === null) return [];
    const m = r.triage.confusion;
    return [{
      config, label, side, highlight: highlight ?? false,
      found: Math.round(c.recall * c.support), total: c.support,
      invented: (m.irrelevant?.actionable ?? 0) + (m.irrelevant?.tentative ?? 0),
    }];
  });
}

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

export function renderChart(points: ChartPoint[]): string {
  if (points.length === 0) throw new Error('No hay resultados con la métrica de conexiones para el gráfico');
  const W = 760, H = 470, left = 78, right = 40, top = 70, bottom = 78;
  const total = points[0].total;
  const xMax = Math.max(10, Math.ceil(Math.max(...points.map(p => p.invented)) / 10) * 10);
  const yMin = Math.max(0, Math.floor((Math.min(...points.map(p => p.found)) - 6) / 10) * 10);
  const x = (v: number) => left + (v / xMax) * (W - left - right);
  const y = (v: number) => top + (1 - (v - yMin) / (total - yMin)) * (H - top - bottom);
  const ink = '#1c1b19', ink2 = '#4a4741', ink3 = '#57534c', line = '#d6d2cb', ember = '#a83b0d', ash = '#57534c';
  const font = `font-family="Hanken Grotesk, system-ui, -apple-system, 'Segoe UI', sans-serif"`;

  const xTicks = Array.from({ length: xMax / 5 + 1 }, (_, i) => i * 5);
  const yTicks: number[] = [];
  for (let v = yMin; v <= total; v += 10) yTicks.push(v);
  if (yTicks[yTicks.length - 1] !== total) yTicks.push(total);

  // Above and below labels hang off a short leader line, right-aligned to the plot edge, so two
  // neighbouring points never share a label position
  const placed = points.map(p => {
    const cx = x(p.invented), cy = y(p.found);
    switch (p.side) {
      case 'right': return { p, anchor: 'start', tx: cx + 13, ty: cy - 3, leader: '' };
      case 'left': return { p, anchor: 'end', tx: cx - 13, ty: cy - 3, leader: '' };
      case 'above': return { p, anchor: 'end', tx: W - right, ty: cy - 46, leader: `M${cx} ${cy - 9}V${cy - 30}` };
      case 'below': return { p, anchor: 'end', tx: W - right, ty: cy + 40, leader: `M${cx} ${cy + 9}V${cy + 26}` };
    }
  });

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="t d">
  <title id="t">Connections found and invented by each model</title>
  <desc id="d">${esc(points.map(p => `${p.label}: ${p.found} of ${p.total} found, ${p.invented} invented`).join('; '))}.</desc>
  <rect width="${W}" height="${H}" rx="14" fill="#f9f8f6"/>
  <text x="${left}" y="34" ${font} font-size="17" font-weight="600" fill="${ink}">Connections found vs. connections invented</text>
  <text x="${left}" y="54" ${font} font-size="13" fill="${ink2}">47 articles × 8 projects, labels by the owner; up is better, left is better</text>
  ${yTicks.map(v => `<line x1="${left}" x2="${W - right}" y1="${y(v)}" y2="${y(v)}" stroke="${line}" stroke-width="1"/>
  <text x="${left - 10}" y="${y(v) + 4}" text-anchor="end" ${font} font-size="12" fill="${ink3}">${v}</text>`).join('\n  ')}
  ${xTicks.map(v => `<text x="${x(v)}" y="${H - bottom + 20}" text-anchor="middle" ${font} font-size="12" fill="${ink3}">${v}</text>`).join('\n  ')}
  <line x1="${left}" x2="${W - right}" y1="${H - bottom}" y2="${H - bottom}" stroke="${ink3}" stroke-width="1"/>
  <text x="${left + (W - left - right) / 2}" y="${H - 22}" text-anchor="middle" ${font} font-size="13" fill="${ink2}">Invented: pairs labeled irrelevant that the model called actionable or tentative</text>
  <text transform="translate(22 ${top + (H - top - bottom) / 2}) rotate(-90)" text-anchor="middle" ${font} font-size="13" fill="${ink2}">Found, of ${total} labeled connections</text>
  ${placed.map(({ p, anchor, tx, ty, leader }) => `${leader ? `<path d="${leader}" stroke="${ink3}" stroke-width="1"/>\n  ` : ''}<circle cx="${x(p.invented)}" cy="${y(p.found)}" r="${p.highlight ? 8 : 6.5}" fill="${p.highlight ? ember : ash}" stroke="#f9f8f6" stroke-width="2"/>
  <text x="${tx}" y="${ty}" text-anchor="${anchor}" ${font} font-size="13" font-weight="${p.highlight ? 600 : 400}" fill="${ink}">${esc(p.label)}</text>
  <text x="${tx}" y="${ty + 16}" text-anchor="${anchor}" ${font} font-size="12" fill="${ink3}">${p.found} found, ${p.invented} invented</text>`).join('\n  ')}
</svg>
`;
}
